set -euo pipefail
INPUT_CSV="${INPUT_CSV:-/path/to/real_data.csv}"
OUTPUT_ROOT="${OUTPUT_ROOT:-/path/to/output_en}"
test -f "${INPUT_CSV}"
python pipeline.py --model copula --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/evaluate_results" --grouping "grouping.json" --constraints "constraints.json" --load_model --output_language "en"
python pipeline.py --model ctgan --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/evaluate_results" --grouping "grouping.json" --constraints "constraints.json" --load_model --output_language "en"
python pipeline.py --model tvae --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/evaluate_results" --grouping "grouping.json" --constraints "constraints.json" --load_model --output_language "en"
python pipeline.py --model tabddpm --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/evaluate_results" --grouping "grouping.json" --constraints "constraints.json" --load_model --output_language "en"
python pipeline.py --model copula --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/ablation/grouping_and_constraints_effect/results" --load_model --output_language "en"
python pipeline.py --model copula --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/ablation/grouping_and_constraints_effect/results_constraints" --constraints "constraints.json" --load_model --output_language "en"
mkdir -p "${OUTPUT_ROOT}/ablation/grouping_and_constraints_effect/results_grouping_constraints/copula"
cp -R "${OUTPUT_ROOT}/evaluate_results/copula/." "${OUTPUT_ROOT}/ablation/grouping_and_constraints_effect/results_grouping_constraints/copula/"
python nsample_sensitivity.py --model copula --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/nsample_sensitivity" --grouping "grouping.json" --constraints "constraints.json" --output_language "en"
python pipeline.py --model copula --n_samples 50000 --input "${INPUT_CSV}" --output_root "${OUTPUT_ROOT}/extended_release" --grouping "grouping.json" --constraints "constraints.json" --load_model --output_language "en"
